package mathutil

import "testing"

func TestAbs(t *testing.T) {
	cases := []struct {
		name  string
		input int
		want  int
	}{
		{name: "positive stays positive", input: 5, want: 5},
		{name: "negative becomes positive", input: -5, want: 5},
		{name: "zero stays zero", input: 0, want: 0},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := Abs(tc.input)
			if got != tc.want {
				t.Errorf("Abs(%d) = %d, want %d", tc.input, got, tc.want)
			}
		})
	}
}

// $ go test -v
// === RUN   TestAbs
// === RUN   TestAbs/positive_stays_positive
// --- PASS: TestAbs/positive_stays_positive (0.00s)
// === RUN   TestAbs/negative_becomes_positive
// --- PASS: TestAbs/negative_becomes_positive (0.00s)
// === RUN   TestAbs/zero_stays_zero
// --- PASS: TestAbs/zero_stays_zero (0.00s)
// --- PASS: TestAbs (0.00s)

package config

import "testing"

func TestParsePort(t *testing.T) {
	cases := []struct {
		name    string
		input   string
		want    int
		wantErr bool
	}{
		{name: "valid port", input: "8080", want: 8080, wantErr: false},
		{name: "empty string", input: "", want: 0, wantErr: true},
		{name: "non-numeric", input: "abc", want: 0, wantErr: true},
		{name: "negative number", input: "-1", want: 0, wantErr: true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := ParsePort(tc.input)
			if (err != nil) != tc.wantErr {
				t.Fatalf("ParsePort(%q) error = %v, wantErr %v", tc.input, err, tc.wantErr)
			}
			if err == nil && got != tc.want {
				t.Errorf("ParsePort(%q) = %d, want %d", tc.input, got, tc.want)
			}
		})
	}
}

// Vulnerable on Go < 1.22 -- every parallel subtest may see the SAME, final tc
for _, tc := range cases {
	t.Run(tc.name, func(t *testing.T) {
		t.Parallel()
		got := IsPalindrome(tc.input)   // tc might not be THIS iteration's value by the time this runs
		if got != tc.want {
			t.Errorf("IsPalindrome(%q) = %v, want %v", tc.input, got, tc.want)
		}
	})
}

// Correct on every Go version -- tc is explicitly shadowed per iteration
for _, tc := range cases {
	tc := tc   // shadow: THIS subtest's own tc, frozen at this exact iteration
	t.Run(tc.name, func(t *testing.T) {
		t.Parallel()
		got := IsPalindrome(tc.input)
		if got != tc.want {
			t.Errorf("IsPalindrome(%q) = %v, want %v", tc.input, got, tc.want)
		}
	})
}

