package stringutil

import "testing"

func BenchmarkConcat(b *testing.B) {
	for i := 0; i < b.N; i++ {
		_ = "hello" + " " + "world"
	}
}

func BenchmarkSprintf(b *testing.B) {
	for i := 0; i < b.N; i++ {
		_ = fmt.Sprintf("%s %s", "hello", "world")
	}
}

// $ go test -bench=. -run=^$ -benchmem
// BenchmarkConcat-8     1000000000         0.35 ns/op        0 B/op        0 allocs/op
// BenchmarkSprintf-8      5000000          312 ns/op        32 B/op        2 allocs/op

package mathutil

import "testing"

func fib(n int) int {
	if n < 2 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

// SUSPECT: result is discarded every iteration -- a smart-enough compiler MIGHT skip real work
func BenchmarkFibBad(b *testing.B) {
	for i := 0; i < b.N; i++ {
		fib(20)
	}
}

var sink int

// SAFE: result flows to a package-level variable, which the compiler cannot prove is unused
func BenchmarkFibGood(b *testing.B) {
	var r int
	for i := 0; i < b.N; i++ {
		r = fib(20)
	}
	sink = r
}

package search

import (
	"sort"
	"testing"
)

func buildSortedSlice(n int) []int {
	data := make([]int, n)
	for i := range data {
		data[i] = i * 2
	}
	return data
}

func BenchmarkBinarySearch(b *testing.B) {
	data := buildSortedSlice(1_000_000)   // one-time setup, irrelevant to the operation being measured
	b.ResetTimer()

	for i := 0; i < b.N; i++ {
		_ = sort.SearchInts(data, 500_000)
	}
}

